def group_consecutive(values):
    if not isinstance(values, (list, tuple)):
        raise ValueError("values must be a list or tuple")
    for v in values:
        if isinstance(v, bool) or not isinstance(v, int):
            raise ValueError("all elements must be int (bool not allowed)")
    if not values:
        return []
    nums = sorted(set(values))
    result = []
    start = prev = nums[0]
    for n in nums[1:]:
        if n == prev + 1:
            prev = n
        else:
            result.append((start, prev))
            start = prev = n
    result.append((start, prev))
    return result
```

